INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 1, 0, 0.0, "あたしだって\nやるときはやるよ！", 24, "2020/04/30 12:00:00", 0.0, 24001, "リン", 1, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 1, 1, 0.0, "ふぅ…\nこれであたしの仕事は\n終わりだね", 24, "2020/04/30 12:00:00", 0.0, 24002, "リン", 1, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 1, 2, 0.0, "終わった終わった\n一人でもなんとか\nなるもんだね", 24, "2020/04/30 12:00:00", 0.0, 24003, "リン", 1, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 2, 3, 0.0, "やったね！\nこれでようやく\nサボれるよ…", 24, "2020/04/30 12:00:00", 0.0, 24004, "リン", 2, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 1, 4, 0.0, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 24, "2020/04/30 12:00:00", 0.0, 24005, "リン", 1, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 2, 5, 0.0, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 24, "2020/04/30 12:00:00", 0.0, 24006, "リン", 2, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 2, 6, 0.0, "あたしも意外と\nやるもんでしょ？", 24, "2020/04/30 12:00:00", 0.0, 24007, "リン", 2, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 7, 0.0, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 24, "2020/04/30 12:00:00", 0.0, 24008, "リン", 4, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 8, 0.0, "このままじゃ\nまっひ～に\n叱られちゃうよ", 24, "2020/04/30 12:00:00", 0.0, 24009, "リン", 4, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 9, 0.0, "まじめに\nやったんだけどな…\n悔しいな～", 24, "2020/04/30 12:00:00", 0.0, 24010, "リン", 4, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 10, 0.0, "やられた…\nねずみって意外と\nてごわいね", 24, "2020/04/30 12:00:00", 0.0, 24011, "リン", 4, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 11, 0.0, "おのれ～\nあたしのチーズを\n盗みやがって～！", 24, "2020/04/30 12:00:00", 0.0, 24012, "リン", 4, 102601, 0.0, 10040);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 4, 12, 0.0, "疲れた…\nけど、次こそは\n守り抜くよ…", 24, "2020/04/30 12:00:00", 1.81, 24013, "リン", 1, 102601, 0.0, 10040);
